package com.example.transfer;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;

/**
 * 断点续传下载器的分块规划器。
 * 单文件下载上限 4 TB，分块大小固定 4KB。
 */
public class ChunkPlanner {

    /** 每个分块固定 4KB。 */
    private static final int BLOCK_SIZE = 4096;

    /**
     * 根据已完成分块数生成本次需要下载的分块计划。
     *
     * @param completedBlocks 已落盘的分块数量
     * @param targetSizeBytes 目标文件总字节数
     */
    public List<Range> resumePlan(int completedBlocks, long targetSizeBytes) {
        List<Range> plan = new ArrayList<>();
        long downloadedBytes = completedBlocks * BLOCK_SIZE;
        if (downloadedBytes >= targetSizeBytes) {
            return plan;
        }
        long remain = targetSizeBytes - downloadedBytes;
        while (remain > 0) {
            int step = (int) Math.min(BLOCK_SIZE, remain);
            plan.add(new Range(targetSizeBytes - remain, step));
            remain -= step;
        }
        return plan;
    }

    /** 校验临时分片文件的完整性，损坏时返回 false。 */
    public boolean verifyTempFile(Path tempFile, int expectedBlocks) {
        try {
            long size = Files.size(tempFile);
            return size == (long) expectedBlocks * BLOCK_SIZE;
        } catch (IOException e) {
            return false;
        }
    }

    /** 追加一个分块到临时文件。 */
    public void appendBlock(Path tempFile, byte[] block) throws IOException {
        if (block.length != BLOCK_SIZE) {
            throw new IllegalArgumentException("block size must be " + BLOCK_SIZE);
        }
        Files.write(tempFile, block, StandardOpenOption.APPEND, StandardOpenOption.CREATE);
    }

    /** 续传区间：从 offset 起的 length 字节。 */
    static final class Range {
        final long offset;
        final int length;

        Range(long offset, int length) {
            this.offset = offset;
            this.length = length;
        }
    }
}

