package com.example.logmask;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 日志脱敏过滤器：按规则对日志行执行掩码替换。
 * 先应用内置规则，再按注册顺序应用租户自定义规则；单条日志行最长 64KB。
 */
public class LogMasker {

    /** 内置规则：手机号掩码。 */
    private static final Pattern PHONE = Pattern.compile("(?<!\\d)1\\d{10}(?!\\d)");

    /** 租户自定义规则，按注册顺序应用。 */
    private final List<Rule> rules = new ArrayList<>();

    /**
     * 注册一条租户自定义脱敏规则。
     *
     * @param ruleId      规则唯一标识
     * @param pattern     租户通过 OpenAPI 提交的正则表达式
     * @param replacement 掩码替换文本
     */
    public void addRule(String ruleId, String pattern, String replacement) {
        if (ruleId == null || ruleId.isEmpty()) {
            throw new IllegalArgumentException("ruleId is required");
        }
        if (pattern == null || pattern.isEmpty()) {
            throw new IllegalArgumentException("pattern is required");
        }
        if (findRule(ruleId) != null) {
            throw new IllegalArgumentException("duplicate rule: " + ruleId);
        }
        rules.add(new Rule(ruleId, Pattern.compile(pattern), replacement));
    }

    /** 对一行日志依次应用内置与自定义规则，返回脱敏后的文本。 */
    public String mask(String rawLine) {
        String line = rawLine == null ? "" : rawLine;
        line = apply(line, PHONE, "[PHONE]");
        for (Rule rule : rules) {
            line = apply(line, rule.pattern, rule.replacement);
        }
        return line;
    }

    private static String apply(String line, Pattern pattern, String replacement) {
        Matcher m = pattern.matcher(line);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            m.appendReplacement(sb, replacement);
        }
        m.appendTail(sb);
        return sb.toString();
    }

    /** 按 id 查找规则，不存在返回 null。 */
    private Rule findRule(String ruleId) {
        for (Rule rule : rules) {
            if (rule.id.equals(ruleId)) {
                return rule;
            }
        }
        return null;
    }

    /** 已注册的租户规则数量。 */
    public int ruleCount() {
        return rules.size();
    }

    private static final class Rule {
        final String id;
        final Pattern pattern;
        final String replacement;

        Rule(String id, Pattern pattern, String replacement) {
            this.id = id;
            this.pattern = pattern;
            this.replacement = replacement;
        }
    }
}

