package com.example.session;

import java.util.HashSet;
import java.util.Set;

/**
 * 访客去重登记表：以 visitorId 唯一标识一个访客。
 */
public class VisitorRegistry {

    static final class Visitor {
        private String visitorId;
        private String lastPath;

        Visitor(String visitorId) {
            this.visitorId = visitorId;
        }

        String getVisitorId() {
            return visitorId;
        }

        void visit(String path) {
            this.lastPath = path;
        }

        void renameTo(String newId) {
            this.visitorId = newId;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Visitor)) return false;
            return visitorId.equals(((Visitor) o).visitorId);
        }

        @Override
        public int hashCode() {
            return visitorId.hashCode();
        }
    }

    private final Set<Visitor> visitors = new HashSet<>();

    /** 登记访客，返回 true 表示新访客，false 表示重复访客 */
    boolean register(Visitor v) {
        if (visitors.contains(v)) {
            return false;
        }
        visitors.add(v);
        return true;
    }

    /** 访客换绑新 ID 后重新登记，保证集合中不出现重复 */
    void migrate(Visitor v, String newId) {
        v.renameTo(newId);
        register(v);
    }

    int size() {
        return visitors.size();
    }
}

