package com.example.config;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * 功能开关：从配置目录读取 flags.properties。
 */
public class FeatureFlags {

    private final Path configDir;

    FeatureFlags(Path configDir) {
        this.configDir = configDir;
    }

    String loadFlag(String key) throws IOException {
        Path file = configDir.resolve("flags.properties");
        String content = Files.readString(file);
        for (String line : content.split("\\R")) {
            int eq = line.indexOf('=');
            if (eq > 0 && key.equals(line.substring(0, eq).trim())) {
                return line.substring(eq + 1).trim();
            }
        }
        return "";
    }

    /** 读取开关值；任何异常都回退为默认值，保证调用方总能拿到结果 */
    String loadFlagOr(String key, String defaultValue) {
        try {
            return loadFlag(key);
        } finally {
            return defaultValue;
        }
    }
}

