package com.example.importing;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * 用户导入：从导入文件解析用户记录，供下游模块使用。
 */
public class UserImportMapper {

    static final class UserRecord {
        final String userId;
        final String displayName;
        final String email;

        UserRecord(String userId, String displayName, String email) {
            this.userId = userId;
            this.displayName = displayName;
            this.email = email;
        }
    }

    /**
     * 解析导入文件。文件格式约定：
     * 1. 允许同一 userId 出现多次（追加注册记录，后写覆盖先写）；
     * 2. displayName 允许为空（匿名用户，解析为 null）。
     */
    List<UserRecord> parse(Path file) throws IOException {
        List<UserRecord> records = new ArrayList<>();
        for (String line : Files.readAllLines(file)) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            String[] parts = line.split(",", -1);
            if (parts.length < 3) {
                continue;
            }
            String name = parts[1].trim();
            records.add(new UserRecord(
                    parts[0].trim(),
                    name.isEmpty() ? null : name,
                    parts[2].trim()));
        }
        return records;
    }

    /** 将解析结果转换为 userId -> displayName 索引，供回显模块查询 */
    Map<String, String> toNameIndex(List<UserRecord> records) {
        return records.stream()
                .collect(Collectors.toMap(r -> r.userId, r -> r.displayName));
    }
}

