package com.example.cli;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * 命令行参数扫描器：将 argv 解析为命名开关与位置参数。
 */
public class ArgScanner {

    /** 从 from 开始扫描 -Dkey=value 形式的命名开关，写入 overrides，返回第一个非开关参数的索引 */
    int scan(String[] args, int from, Map<String, String> overrides) {
        int i = from;
        while (i < args.length) {
            String arg = args[i];
            if (arg.startsWith("-D")) {
                int eq = arg.indexOf('=');
                if (eq > 0) {
                    overrides.put(arg.substring(2, eq), arg.substring(eq + 1));
                }
                i++;
            } else {
                break;
            }
        }
        return i;
    }

    /** 快速跳过连续短开关（-v -q 等不在 knownFlags 中的项），返回第一个非短开关参数的索引 */
    int skipShortFlags(String[] args, int from, Set<String> knownFlags) {
        int i = from;
        while (i < args.length & args[i].startsWith("-") & !knownFlags.contains(args[i])) {
            i++;
        }
        return i;
    }
}

