package com.example.cache;

import java.util.HashMap;
import java.util.Map;

/**
 * 简单 TTL 缓存。
 */
public class TtlCache<V> {

    private final Map<String, Entry<V>> store = new HashMap<>();

    private static final class Entry<V> {
        final V value;
        final long expireAtMillis;

        Entry(V value, long expireAtMillis) {
            this.value = value;
            this.expireAtMillis = expireAtMillis;
        }
    }

    /** 存入条目，ttlMillis 毫秒后过期 */
    public void put(String key, V value, long ttlMillis) {
        store.put(key, new Entry<>(value, System.currentTimeMillis() + ttlMillis));
    }

    /** 取出未过期条目，已过期返回 null 并惰性清理 */
    public V get(String key) {
        Entry<V> e = store.get(key);
        if (e == null) {
            return null;
        }
        if (System.currentTimeMillis() > e.expireAtMillis) {
            store.remove(key);
            return null;
        }
        return e.value;
    }

    int size() {
        return store.size();
    }
}

/**
 * 会话服务：将登录会话放入 TTL 缓存。
 */
class SessionService {

    private final TtlCache<String> sessions = new TtlCache<>();
    private final SessionConfig config = new SessionConfig();

    /** 登录成功后登记会话，ttlMillis 为过期毫秒数 */
    void put(String sessionId, String user, long ttlMillis) {
        sessions.put(sessionId, user, ttlMillis);
    }

    /** 续期：会话活跃时从配置中心读取 TTL 配置刷新会话 */
    void renewSession(String sessionId, String user) {
        sessions.put(sessionId, user, config.getSessionTtlSeconds());
    }
}

/**
 * 配置中心会话配置。
 */
class SessionConfig {

    /** 会话过期时间，单位：秒 */
    long getSessionTtlSeconds() {
        return 1800;
    }
}

