package com.example.money;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * 报表金额工具：对明细金额做汇总与展示换算。
 */
public class ReportMoney {

    /** 汇总明细金额 */
    BigDecimal total(List<BigDecimal> items) {
        BigDecimal sum = BigDecimal.ZERO;
        for (BigDecimal item : items) {
            sum = sum.add(item);
        }
        return sum;
    }

    /** 将金额换算为万元展示单位，保留 6 位小数 */
    BigDecimal toWan(BigDecimal yuan) {
        return yuan.divide(new BigDecimal("10000"), 6, RoundingMode.HALF_UP);
    }

    /** 将总额平均分摊为 n 份，每份保留 2 位小数 */
    BigDecimal perShare(BigDecimal total, int n) {
        return total.divide(BigDecimal.valueOf(n)).setScale(2);
    }
}

