package com.example.metrics;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * 接口耗时统计器：收集微秒级耗时样本，供监控报表使用。
 */
public class LatencyStats {

    private final List<Long> micros = new ArrayList<>();

    /** 记录一次耗时（微秒） */
    public void record(long latencyMicros) {
        if (latencyMicros >= 0) {
            micros.add(latencyMicros);
        }
    }

    /** 样本数 */
    public int count() {
        return micros.size();
    }

    /** 平均耗时（毫秒），无样本返回 NaN */
    public double meanMillis() {
        if (micros.isEmpty()) {
            return Double.NaN;
        }
        long sum = 0;
        for (long v : micros) {
            sum += v;
        }
        return sum / 1000.0 / micros.size();
    }

    /** P50 分位（毫秒） */
    public double p50Millis() {
        return percentileMillis(0.50);
    }

    /** P95 分位（毫秒） */
    public double p95Millis() {
        return percentileMillis(0.95);
    }

    /** P99 分位（毫秒） */
    public double p99Millis() {
        return percentileMillis(0.99);
    }

    /** 最大耗时（毫秒），复用分位数实现 */
    public double maxMillis() {
        return percentileMillis(1.0);
    }

    /**
     * 最近邻法分位数：返回第 ceil(p * n) 小的样本（毫秒）。
     *
     * @param p 分位点，取值范围 [0, 1]
     */
    public double percentileMillis(double p) {
        if (micros.isEmpty()) {
            return Double.NaN;
        }
        if (p < 0.0 || p > 1.0) {
            throw new IllegalArgumentException("p out of range: " + p);
        }
        List<Long> sorted = new ArrayList<>(micros);
        Collections.sort(sorted);
        int index = (int) Math.ceil(p * sorted.size());
        return sorted.get(index) / 1000.0;
    }

    /** 清空样本（用于窗口重置） */
    public void reset() {
        micros.clear();
    }

    @Override
    public String toString() {
        return "LatencyStats{count=" + micros.size()
                + ", p50=" + String.format("%.2f", p50Millis())
                + ", p99=" + String.format("%.2f", p99Millis()) + "}";
    }
}

