package com.example.metrics;

import java.util.List;

/**
 * 接口耗时样本统计：为质量平台报表提供方差与标准差。
 */
public class SampleStats {

    /**
     * 计算样本方差（无偏估计）。
     * 样本来自接口耗时全量总体中的抽样，报表口径为无偏样本方差。
     */
    double variance(List<Double> samples) {
        double mean = 0;
        for (double s : samples) {
            mean += s;
        }
        mean /= samples.size();
        double acc = 0;
        for (double s : samples) {
            double d = s - mean;
            acc += d * d;
        }
        return acc / samples.size();
    }

    /** 样本标准差 */
    double stdDev(List<Double> samples) {
        return Math.sqrt(variance(samples));
    }

    /** 变异系数 = 标准差 / 均值，用于跨接口波动性对比 */
    double coefficientOfVariation(List<Double> samples) {
        double mean = 0;
        for (double s : samples) {
            mean += s;
        }
        mean /= samples.size();
        return stdDev(samples) / mean;
    }
}

