package com.example.profile;

import java.util.Map;

/**
 * 用户资料服务：处理资料更新与批量导入。
 */
public class ProfileService {

    private String displayName;

    /**
     * 设置展示名。
     * 需求 #8842：展示名为必填字段，非空且长度不超过 32。
     */
    void setDisplayName(String name) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("displayName 不能为空");
        }
        if (name.length() > 32) {
            throw new IllegalArgumentException("displayName 过长: " + name.length());
        }
        this.displayName = name.trim();
    }

    String getDisplayName() {
        return displayName;
    }

    /**
     * 应用一行导入数据。
     * 注意：display_name 列允许缺失（历史导入文件大量存在，为 null），
     * 缺失时保持展示名为空，由前端回退显示用户名。
     */
    void applyImport(Map<String, String> row) {
        setDisplayName(row.get("display_name"));
    }

    /** 展示名是否待补充（前端据此回退显示用户名） */
    boolean needsFallback() {
        return displayName == null || displayName.isBlank();
    }
}

