package com.example.policy;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * 访问策略：白名单命中即跳过风控二次校验。
 */
public class PolicyChecker {

    private final Set<Long> whitelist = new HashSet<>();

    /** 装载白名单，来源为 DB bigint 主键 */
    void loadWhitelist(List<Long> ids) {
        whitelist.clear();
        whitelist.addAll(ids);
    }

    int size() {
        return whitelist.size();
    }

    /**
     * 批量校验：风控模块传入的候选用户 id 列表中
     * 任一命中白名单即放行整批请求。
     */
    boolean anyWhitelisted(List<Integer> ids) {
        for (Integer id : ids) {
            if (whitelist.contains(id)) {
                return true;
            }
        }
        return false;
    }

    /** 导出白名单副本，供配置对账 */
    Set<Long> snapshot() {
        return new HashSet<>(whitelist);
    }
}
